use wasm_bindgen::prelude::*;
use image::{DynamicImage, RgbaImage, ImageReader};
use std::io::Cursor;

use burn::module::Module;
use burn::tensor::Tensor;
use burn_ndarray::NdArray;

// Hook initialization for detailed panic backtraces in the browser console
#[wasm_bindgen]
pub fn init_panic_hook() {
    console_error_panic_hook::set_once();
}

// Module including the model code generated by burn-import directly inside src/
mod model {
    pub mod generated {
        #![allow(clippy::all)]
        include!("plant_disease_model.rs");
    }
}

type Backend = NdArray<f32>;

#[wasm_bindgen]
pub struct ProcessedResult {
    rgba_bytes: Vec<u8>,
    normalized_tensor: Vec<f32>,
}

#[wasm_bindgen]
impl ProcessedResult {
    #[wasm_bindgen(getter)]
    pub fn rgba_bytes(&self) -> Vec<u8> {
        self.rgba_bytes.clone()
    }

    #[wasm_bindgen(getter)]
    pub fn normalized_tensor(&self) -> Vec<f32> {
        self.normalized_tensor.clone()
    }
}

/// Image filtering configuration
#[wasm_bindgen]
pub struct FilterOptions {
    pub contrast: f32,    // Range: -100.0 to 100.0 (0.0 = default)
    pub brightness: i32,  // Range: -255 to 255 (0 = default)
    pub blur_sigma: f32,  // Range: 0.0 to 10.0 (0.0 = no blur)
    pub grayscale: bool,  // Convert to grayscale
}

#[wasm_bindgen]
impl FilterOptions {
    #[wasm_bindgen(constructor)]
    pub fn new(contrast: f32, brightness: i32, blur_sigma: f32, grayscale: bool) -> Self {
        Self {
            contrast,
            brightness,
            blur_sigma,
            grayscale,
        }
    }
}

/// Image processing pipeline:
/// Decode -> EXIF Orientation -> Filters -> Resize (224x224) -> HSV Leaf Segmentation -> ImageNet Normalization
#[wasm_bindgen]
pub fn process_image_full(
    image_bytes: &[u8],
    filters: Option<FilterOptions>,
) -> Result<ProcessedResult, JsValue> {
    console_error_panic_hook::set_once();

    // Decode image
    let reader = ImageReader::new(Cursor::new(image_bytes))
        .with_guessed_format()
        .map_err(|e| JsValue::from_str(&format!("Failed to guess image format: {}", e)))?;

    let mut img = reader
        .decode()
        .map_err(|e| JsValue::from_str(&format!("Failed to decode image bytes: {}", e)))?;

    // EXIF orientation fix
    img = apply_exif_orientation(image_bytes, img);

    // Apply optional user filters
    if let Some(opts) = filters {
        img = apply_image_filters(img, &opts);
    }

    // Resize to neural network input shape (224x224)
    let resized = img.resize_exact(224, 224, image::imageops::FilterType::Lanczos3);
    let mut rgba_img = resized.to_rgba8();

    // Isolate leaf area in HSV space
    segment_leaf_hsv(&mut rgba_img);

    // ImageNet normalization in NCHW layout (1x3x224x224)
    let mean = [0.485f32, 0.456, 0.406];
    let std = [0.229f32, 0.224, 0.225];
    let plane_size = 224 * 224;
    let mut normalized_tensor = vec![0.0f32; 3 * plane_size];

    for y in 0..224 {
        for x in 0..224 {
            let pixel = rgba_img.get_pixel(x, y);
            let idx = (y * 224 + x) as usize;

            let r = (pixel[0] as f32 / 255.0 - mean[0]) / std[0];
            let g = (pixel[1] as f32 / 255.0 - mean[1]) / std[1];
            let b = (pixel[2] as f32 / 255.0 - mean[2]) / std[2];

            // CHW channel ordering: R plane | G plane | B plane
            normalized_tensor[idx] = r;
            normalized_tensor[plane_size + idx] = g;
            normalized_tensor[2 * plane_size + idx] = b;
        }
    }

    Ok(ProcessedResult {
        rgba_bytes: rgba_img.into_raw(),
        normalized_tensor,
    })
}

/// Runs inference on the normalized tensor using the embedded Burn model
#[wasm_bindgen]
pub fn predict_disease(normalized_tensor: &[f32]) -> Result<Vec<f32>, JsValue> {
    console_error_panic_hook::set_once();

    if normalized_tensor.len() != 1 * 3 * 224 * 224 {
        return Err(JsValue::from_str(&format!(
            "Invalid tensor length. Expected {}, got {}",
            1 * 3 * 224 * 224,
            normalized_tensor.len()
        )));
    }

    // Initialize backend device
    let device = Default::default();

    // Instantiate the model directly using the device
    let model = model::generated::Model::new(&device);

    // Create Burn tensor
    let tensor_data = burn::tensor::TensorData::new(normalized_tensor.to_vec(), [1, 3, 224, 224]);
    let input_tensor = Tensor::<Backend, 4>::from_data(tensor_data, &device);

    // Forward pass
    let output_logits = model.forward(input_tensor);

    // Select correct softmax axis based on output dimensions
    let dims = output_logits.dims();
    let softmax_axis = if dims.len() > 1 { 1 } else { 0 };

    // Convert raw logits to probabilities via Softmax along class axis
    let probabilities = burn::tensor::activation::softmax(output_logits, softmax_axis);

    // Extract output vector
    let probs_vec: Vec<f32> = probabilities
        .into_data()
        .into_vec::<f32>()
        .map_err(|e| JsValue::from_str(&format!("Failed to convert tensor data: {:?}", e)))?;

    Ok(probs_vec)
}

fn apply_image_filters(mut img: DynamicImage, filters: &FilterOptions) -> DynamicImage {
    if filters.grayscale {
        img = img.grayscale();
    }
    if filters.contrast != 0.0 {
        img = img.adjust_contrast(filters.contrast);
    }
    if filters.brightness != 0 {
        img = img.brighten(filters.brightness);
    }
    if filters.blur_sigma > 0.0 {
        img = img.blur(filters.blur_sigma);
    }
    img
}

fn segment_leaf_hsv(img: &mut RgbaImage) {
    for pixel in img.pixels_mut() {
        let r = pixel[0] as f32;
        let g = pixel[1] as f32;
        let b = pixel[2] as f32;

        let max = r.max(g).max(b);
        let min = r.min(g).min(b);
        let chroma = max - min;

        // Leaf greens: green channel dominant
        let is_green = g > r && g > b;

        // Disease spots/lesions: brown/yellow tones with moderate color difference
        let is_brown_lesion = r > b && g > (b * 0.8) && chroma > 15.0;

        // Require minimum chroma (>20) to filter out neutral grey/black/white backgrounds
        let is_leaf = chroma >= 20.0 && (is_green || is_brown_lesion);

        if !is_leaf {
            // Mask non-leaf background elements to black
            pixel[0] = 0;
            pixel[1] = 0;
            pixel[2] = 0;
            pixel[3] = 255;
        }
    }
}

fn rgb_to_hsv(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let delta = max - min;

    let v = max;
    let s = if max == 0.0 { 0.0 } else { delta / max };

    if delta == 0.0 {
        return (0.0, s, v);
    }

    let mut h = if max == r {
        60.0 * (((g - b) / delta) % 6.0)
    } else if max == g {
        60.0 * (((b - r) / delta) + 2.0)
    } else {
        60.0 * (((r - g) / delta) + 4.0)
    };

    if h < 0.0 {
        h += 360.0;
    }

    (h, s, v)
}

fn apply_exif_orientation(raw_bytes: &[u8], img: DynamicImage) -> DynamicImage {
    let mut cursor = Cursor::new(raw_bytes);
    if let Ok(exif_data) = exif::Reader::new().read_from_container(&mut cursor) {
        if let Some(field) = exif_data.get_field(exif::Tag::Orientation, exif::In::PRIMARY) {
            if let Some(orientation) = field.value.get_uint(0) {
                return match orientation {
                    3 => img.rotate180(),
                    6 => img.rotate90(),
                    8 => img.rotate270(),
                    _ => img,
                };
            }
        }
    }
    img
}

#[cfg(test)]
mod tests {
    use super::*;
    use image::{ImageBuffer, Rgb};

    fn create_dummy_png_bytes(width: u32, height: u32) -> Vec<u8> {
        let img = ImageBuffer::from_fn(width, height, |x, _y| {
            if x % 2 == 0 {
                Rgb([0u8, 200u8, 0u8])
            } else {
                Rgb([200u8, 0u8, 0u8])
            }
        });

        let mut bytes: Vec<u8> = Vec::new();
        let mut cursor = Cursor::new(&mut bytes);
        DynamicImage::ImageRgb8(img)
            .write_to(&mut cursor, image::ImageFormat::Png)
            .unwrap();
        bytes
    }

    #[test]
    fn test_rgb_to_hsv_primary_colors() {
        let (h, s, v) = rgb_to_hsv(1.0, 0.0, 0.0);
        assert_eq!(h, 0.0);
        assert_eq!(s, 1.0);
        assert_eq!(v, 1.0);

        let (h, s, v) = rgb_to_hsv(0.0, 1.0, 0.0);
        assert_eq!(h, 120.0);
        assert_eq!(s, 1.0);
        assert_eq!(v, 1.0);

        let (h, s, v) = rgb_to_hsv(0.0, 0.0, 1.0);
        assert_eq!(h, 240.0);
        assert_eq!(s, 1.0);
        assert_eq!(v, 1.0);
    }

    #[test]
    fn test_rgb_to_hsv_grayscale_no_panic() {
        let (h, s, v) = rgb_to_hsv(0.5, 0.5, 0.5);
        assert_eq!(h, 0.0);
        assert_eq!(s, 0.0);
        assert_eq!(v, 0.5);
    }

    #[test]
    fn test_process_image_full_output_dimensions() {
        let png_bytes = create_dummy_png_bytes(100, 100);
        let result = process_image_full(&png_bytes, None);

        assert!(result.is_ok());
        let res = result.unwrap();

        assert_eq!(res.rgba_bytes().len(), 224 * 224 * 4);
        assert_eq!(res.normalized_tensor().len(), 1 * 3 * 224 * 224);
    }

    #[test]
    fn test_process_image_full_with_filters() {
        let png_bytes = create_dummy_png_bytes(50, 50);
        let filters = FilterOptions::new(10.0, 5, 1.0, true);

        let result = process_image_full(&png_bytes, Some(filters));

        assert!(result.is_ok());
        let res = result.unwrap();
        assert_eq!(res.normalized_tensor().len(), 1 * 3 * 224 * 224);
    }

    #[test]
    fn test_leaf_segmentation_hsv() {
        let mut img = RgbaImage::new(1, 2);

        img.put_pixel(0, 0, image::Rgba([0, 200, 0, 255]));   // Green leaf -> keep
        img.put_pixel(0, 1, image::Rgba([128, 128, 128, 255])); // Grey background -> mask to black

        segment_leaf_hsv(&mut img);

        assert_eq!(img.get_pixel(0, 0)[1], 200);
        assert_eq!(img.get_pixel(0, 1)[0], 0);
        assert_eq!(img.get_pixel(0, 1)[1], 0);
        assert_eq!(img.get_pixel(0, 1)[2], 0);
    }
}